function normalizarNome(nome: string) {
  return nome
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .trim()
    .toLowerCase();
}

function obterFotoPorNome(fotosUsuarios: { [nome: string]: string }, nome: string) {
  if (fotosUsuarios[nome]) return fotosUsuarios[nome];

  const nomeNormalizado = normalizarNome(nome);
  const chaveFoto = Object.keys(fotosUsuarios).find(chave => {
    const chaveNormalizada = normalizarNome(chave);
    return (
      chaveNormalizada === nomeNormalizado ||
      nomeNormalizado.includes(chaveNormalizada) ||
      chaveNormalizada.includes(nomeNormalizado)
    );
  });

  return chaveFoto ? fotosUsuarios[chaveFoto] : undefined;
}

function fotosPorUidParaNomes(fotosPorUid: Record<string, unknown>) {
  return Object.entries(fotosPorUid).reduce((acc, [uid, foto]) => {
    const nome = UID_TO_NOME[uid];
    if (nome && typeof foto === 'string') {
      acc[nome] = foto;
    }
    return acc;
  }, {} as Record<string, string>);
}

function montarCropQuadrado(width?: number, height?: number) {
  if (!width || !height) return null;

  const tamanho = Math.min(width, height);
  return {
    originX: Math.max(0, Math.floor((width - tamanho) / 2)),
    originY: Math.max(0, Math.floor((height - tamanho) / 2)),
    width: tamanho,
    height: tamanho,
  };
}

