type CorRgb = {
  r: number;
  g: number;
  b: number;
};

function limitarCanal(valor: number) {
  if (Number.isNaN(valor)) return 0;
  return Math.max(0, Math.min(255, Math.round(valor)));
}

function rgbParaHex({ r, g, b }: CorRgb) {
  return `#${[r, g, b].map(canal => limitarCanal(canal).toString(16).padStart(2, '0')).join('').toUpperCase()}`;
}

function hexParaRgb(hex: string): CorRgb {
  const normalizado = hex.replace('#', '');
  if (normalizado.length !== 6) return { r: 255, g: 255, b: 255 };
  return {
    r: parseInt(normalizado.slice(0, 2), 16),
    g: parseInt(normalizado.slice(2, 4), 16),
    b: parseInt(normalizado.slice(4, 6), 16),
  };
}

function ehUniformeValido(valor: any): valor is UniformeCulto {
  return (
    typeof valor?.corCamiseta === 'string' &&
    /^#[0-9A-Fa-f]{6}$/.test(valor.corCamiseta) &&
    typeof valor?.corCalcaSaia === 'string' &&
    /^#[0-9A-Fa-f]{6}$/.test(valor.corCalcaSaia)
  );
}

function mensagemErroUniforme(error: unknown) {
  const codigo = typeof error === 'object' && error && 'code' in error ? String((error as any).code) : '';
  const mensagem = error instanceof Error ? error.message : String(error || '');

  if (codigo.includes('permission-denied') || mensagem.includes('permission-denied')) {
    return 'Seu usuário ainda não tem permissão no Firestore para salvar o uniforme global.';
  }

  if (mensagem.includes('tempo limite')) {
    return 'O app não conseguiu confirmar o salvamento agora. Verifique a conexão e tente novamente.';
  }

  return `Não foi possível salvar a cor do uniforme.${mensagem ? ` Detalhe: ${mensagem}` : ''}`;
}

function comTempoLimite<T>(promessa: Promise<T>, ms: number, mensagem: string): Promise<T> {
  return Promise.race([
    promessa,
    new Promise<T>((_, reject) => {
      setTimeout(() => reject(new Error(mensagem)), ms);
    }),
  ]);
}

