import React, { useEffect, useState, useRef } from 'react';
import {
  View,
  Text,
  StyleSheet,
  FlatList,
  TextInput,
  TouchableOpacity,
  Alert,
  ActivityIndicator,
  Platform,
  KeyboardAvoidingView,
  Animated,
  Easing,
} from 'react-native';
import { useNavigation } from '@react-navigation/native';
import {
  collection,
  onSnapshot,
  query,
  orderBy,
  deleteDoc,
  doc,
  addDoc,
  updateDoc,
  arrayUnion,
  getDoc,
} from 'firebase/firestore';
import { LinearGradient } from 'expo-linear-gradient';
import { MaterialCommunityIcons, MaterialIcons } from '@expo/vector-icons';
import { firestore, auth } from '../services/firebaseConfig';
import { confirmAction } from '../utils/confirmAction';

const UIDS_PERMITIDOS = [
  'qAvyxYtraUPmd06d3jufwqPi7vo2',
  'g8KmZsmMqfPEqAM3NWF7qs33Gid2',
  'bVpx7GAuLuTbRVWfPOT57vgO9cL2',
];

interface Aviso {
  id?: string;
  titulo: string;
  mensagem: string;
  criadoEm: any;
  visualizadosPor?: string[];
  curtidas?: string[];
}

interface UsuarioInfo {
  nome?: string;
  email?: string;
}

const cardGradients = [
  ['#151C3C', '#222047', '#2D2146'],
  ['#111D34', '#1F2948', '#243657'],
  ['#211B3D', '#24254A', '#18364A'],
];

function GradientButton({ children, onPress, variant = 'primary', style }: any) {
  const colors = variant === 'danger'
    ? ['#FF6B6B', '#D9365E']
    : variant === 'secondary'
      ? ['#67E8F9', '#38BDF8']
      : ['#FFB84D', '#FF7A3D'];

  return (
    <TouchableOpacity onPress={onPress} activeOpacity={0.86} style={[styles.buttonWrap, style]}>
      <LinearGradient colors={colors} start={{ x: 0, y: 0 }} end={{ x: 1, y: 1 }} style={styles.gradientButton}>
        {children}
      </LinearGradient>
    </TouchableOpacity>
  );
}

export default function AvisosScreen() {
  const navigation = useNavigation();
  const [avisos, setAvisos] = useState<Aviso[]>([]);
  const [uidAtual, setUidAtual] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [novoTítulo, setNovoTítulo] = useState('');
  const [novoMensagem, setNovoMensagem] = useState('');
  const [mostrarCamposNovo, setMostrarCamposNovo] = useState(false);
  const [editandoId, setEditandoId] = useState<string | null>(null);
  const [editTítulo, setEditTítulo] = useState('');
  const [editMensagem, setEditMensagem] = useState('');
  const [usuáriosInfo, setUsuariosInfo] = useState<{ [uid: string]: UsuarioInfo }>({});

  const animatedValues = useRef<Animated.Value[]>([]);
  const likeScales = useRef<{ [id: string]: Animated.Value }>({}).current;
  const likeBounces = useRef<{ [id: string]: Animated.Value }>({}).current;
  const likePulse = useRef<{ [id: string]: Animated.Value }>({}).current;
  const likeRing = useRef<{ [id: string]: Animated.Value }>({}).current;

  async function buscarNomesCurtidores(uids: string[]) {
    const novos: { [uid: string]: UsuarioInfo } = { ...usuáriosInfo };
    for (const uid of uids) {
      if (!novos[uid]) {
        try {
          const snap = await getDoc(doc(firestore, 'usuários', uid));
          novos[uid] = snap.exists()
            ? { nome: snap.data().nome || undefined, email: snap.data().email || undefined }
            : { nome: undefined, email: undefined };
        } catch {
          novos[uid] = { nome: undefined, email: undefined };
        }
      }
    }
    setUsuariosInfo(novos);
  }

  const permitido = !!uidAtual && UIDS_PERMITIDOS.includes(uidAtual);

  useEffect(() => {
    const uid = auth.currentUser?.uid ?? null;
    setUidAtual(uid);

    const avisosQuery = query(collection(firestore, 'avisos'), orderBy('criadoEm', 'desc'));

    const unsubscribe = onSnapshot(avisosQuery, async (querySnapshot) => {
      const data = querySnapshot.docs.map(docSnap => ({ id: docSnap.id, ...docSnap.data() }));

      if (uid) {
        await Promise.all(querySnapshot.docs.map(async docSnap => {
          const aviso = docSnap.data() as Aviso;
          if (!aviso.visualizadosPor || !aviso.visualizadosPor.includes(uid)) {
            await updateDoc(doc(firestore, 'avisos', docSnap.id), {
              visualizadosPor: arrayUnion(uid),
            });
          }
        }));
      }

      setAvisos(data as Aviso[]);
      setLoading(false);

      const allUids: string[] = [];
      data.forEach((aviso: Aviso) => {
        aviso.curtidas?.forEach(uidCurtida => {
          if (!allUids.includes(uidCurtida)) allUids.push(uidCurtida);
        });
      });
      if (allUids.length > 0) await buscarNomesCurtidores(allUids);
    }, (error) => {
      console.log('Erro ao buscar avisos:', error);
      setLoading(false);
    });

    return () => unsubscribe();
  }, []);

  useEffect(() => {
    animatedValues.current = avisos.map(() => new Animated.Value(30));
    Animated.stagger(80, animatedValues.current.map(anim =>
      Animated.timing(anim, { toValue: 0, duration: 400, useNativeDriver: true })
    )).start();
  }, [avisos.length]);

  useEffect(() => {
    avisos.forEach(aviso => {
      if (!aviso.id) return;

      if (!likePulse[aviso.id]) likePulse[aviso.id] = new Animated.Value(1);
      if (!likeRing[aviso.id]) likeRing[aviso.id] = new Animated.Value(0);

      const usuárioCurtiu = (aviso.curtidas || []).includes(uidAtual || '');

      if (!usuárioCurtiu) {
        Animated.loop(
          Animated.sequence([
            Animated.timing(likePulse[aviso.id], {
              toValue: 1.18,
              duration: 620,
              easing: Easing.inOut(Easing.ease),
              useNativeDriver: true,
            }),
            Animated.timing(likePulse[aviso.id], {
              toValue: 1,
              duration: 620,
              easing: Easing.inOut(Easing.ease),
              useNativeDriver: true,
            }),
          ])
        ).start();

        Animated.loop(
          Animated.sequence([
            Animated.timing(likeRing[aviso.id], {
              toValue: 1,
              duration: 1200,
              easing: Easing.out(Easing.ease),
              useNativeDriver: true,
            }),
            Animated.timing(likeRing[aviso.id], { toValue: 0, duration: 0, useNativeDriver: true }),
          ])
        ).start();
      } else {
        likePulse[aviso.id].setValue(1);
        likeRing[aviso.id].setValue(0);
      }
    });
  }, [avisos.map(a => a.id + (a.curtidas || []).join(',')).join(',')]);

  const excluirAviso = async (id: string) => {
    if (!uidAtual || !UIDS_PERMITIDOS.includes(uidAtual)) return;
    confirmAction({
      title: 'Excluir aviso',
      message: 'Tem certeza que deseja excluir este aviso?',
      onConfirm: async () => {
        try {
          await auth.currentUser?.getIdToken(true);
          await deleteDoc(doc(firestore, 'avisos', id));
          setAvisos(prev => prev.filter(aviso => aviso.id !== id));
        } catch (error: any) {
          console.log('Erro ao excluir aviso:', error);
        }
      },
    });
  };

  const handleCriarAviso = async () => {
    if (!novoTítulo.trim() || !novoMensagem.trim()) {
      Alert.alert('Atenção', 'Preencha o titulo e a mensagem.');
      return;
    }
    try {
      await addDoc(collection(firestore, 'avisos'), {
        titulo: novoTítulo,
        mensagem: novoMensagem,
        criadoEm: new Date(),
        visualizadosPor: [],
        curtidas: [],
      });
      setNovoTítulo('');
      setNovoMensagem('');
      setMostrarCamposNovo(false);
    } catch {
      Alert.alert('Erro', 'Não foi possível criar o aviso.');
    }
  };

  const handleEditarAviso = (aviso: Aviso) => {
    setEditandoId(aviso.id!);
    setEditTítulo(aviso.titulo);
    setEditMensagem(aviso.mensagem);
  };

  const handleSalvarEdicao = async () => {
    if (!editTítulo.trim() || !editMensagem.trim() || !editandoId) {
      Alert.alert('Atenção', 'Preencha o titulo e a mensagem.');
      return;
    }
    try {
      await updateDoc(doc(firestore, 'avisos', editandoId), {
        titulo: editTítulo,
        mensagem: editMensagem,
      });
      setEditandoId(null);
      setEditTítulo('');
      setEditMensagem('');
    } catch {
      Alert.alert('Erro', 'Não foi possível salvar o aviso.');
    }
  };

  const handleCurtirAviso = async (aviso: Aviso) => {
    if (!uidAtual || !aviso.id) return;
    const avisoDoc = doc(firestore, 'avisos', aviso.id);
    const docSnap = await getDoc(avisoDoc);
    let curtidasArr: string[] = [];
    if (docSnap.exists()) curtidasArr = docSnap.data().curtidas || [];

    if (curtidasArr.includes(uidAtual)) {
      curtidasArr = curtidasArr.filter(uid => uid !== uidAtual);
    } else {
      curtidasArr.push(uidAtual);
    }
    await updateDoc(avisoDoc, { curtidas: curtidasArr });

    if (!likeScales[aviso.id]) likeScales[aviso.id] = new Animated.Value(1);
    Animated.sequence([
      Animated.timing(likeScales[aviso.id], { toValue: 1.28, duration: 120, useNativeDriver: true }),
      Animated.timing(likeScales[aviso.id], { toValue: 1, duration: 120, useNativeDriver: true }),
    ]).start();

    if (!likeBounces[aviso.id]) likeBounces[aviso.id] = new Animated.Value(0);
    likeBounces[aviso.id].setValue(0);
    Animated.sequence([
      Animated.timing(likeBounces[aviso.id], {
        toValue: -14,
        duration: 120,
        easing: Easing.out(Easing.quad),
        useNativeDriver: true,
      }),
      Animated.timing(likeBounces[aviso.id], {
        toValue: 0,
        duration: 180,
        easing: Easing.bounce,
        useNativeDriver: true,
      }),
    ]).start();
  };

  const renderItem = ({ item, index }: { item: Aviso; index: number }) => {
    if (!item.id) return null;

    const curtidas = item.curtidas || [];
    const usuárioCurtiu = curtidas.includes(uidAtual || '');
    const nomesCurtidores = curtidas.map(uid => usuáriosInfo[uid]?.nome).filter(Boolean) as string[];
    const colors = cardGradients[index % cardGradients.length];

    if (!likeScales[item.id]) likeScales[item.id] = new Animated.Value(1);
    if (!likeBounces[item.id]) likeBounces[item.id] = new Animated.Value(0);
    if (!likePulse[item.id]) likePulse[item.id] = new Animated.Value(1);
    if (!likeRing[item.id]) likeRing[item.id] = new Animated.Value(0);

    const ringScale = likeRing[item.id].interpolate({ inputRange: [0, 1], outputRange: [1, 2.35] });
    const ringOpacity = likeRing[item.id].interpolate({ inputRange: [0, 0.7, 1], outputRange: [0.5, 0.22, 0] });
    const likeTransform = usuárioCurtiu
      ? { transform: [{ scale: likeScales[item.id] }, { translateY: likeBounces[item.id] }] }
      : { transform: [{ scale: likePulse[item.id] }, { translateY: likeBounces[item.id] }] };

    return (
      <Animated.View
        style={{
          transform: [{ translateY: animatedValues.current[index] || new Animated.Value(0) }],
          opacity: animatedValues.current[index]
            ? animatedValues.current[index].interpolate({ inputRange: [0, 30], outputRange: [1, 0.7] })
            : 1,
        }}
      >
        <LinearGradient colors={['#FFB84D', '#43E97B', '#46D7FF']} start={{ x: 0, y: 0 }} end={{ x: 1, y: 1 }} style={styles.avisoBorder}>
          <LinearGradient colors={colors} start={{ x: 0, y: 0 }} end={{ x: 1, y: 1 }} style={styles.avisoCard}>
            <View style={styles.cardGlow} />
            {editandoId === item.id && permitido ? (
              <>
                <TextInput style={styles.input} value={editTítulo} onChangeText={setEditTítulo} placeholder="Título" placeholderTextColor="#BFD7FF" />
                <TextInput style={[styles.input, styles.textArea]} value={editMensagem} onChangeText={setEditMensagem} multiline placeholder="Mensagem" placeholderTextColor="#BFD7FF" />
                <View style={styles.row}>
                  <GradientButton style={{ flex: 1, marginRight: 8 }} onPress={handleSalvarEdicao}>
                    <Text style={styles.gradientButtonText}>Salvar</Text>
                  </GradientButton>
                  <GradientButton style={{ flex: 1, marginLeft: 8 }} onPress={() => setEditandoId(null)} variant="secondary">
                    <Text style={styles.gradientButtonText}>Cancelar</Text>
                  </GradientButton>
                </View>
              </>
            ) : (
              <>
                <View style={styles.avisoHeader}>
                  <View style={styles.avisoIconCircle}>
                    <MaterialCommunityIcons name="bullhorn-outline" size={24} color="#111827" />
                  </View>
                  <View style={{ flex: 1 }}>
                    <Text style={styles.avisoTítulo}>{item.titulo}</Text>
                    <Text style={styles.avisoData}>{item.criadoEm?.toDate ? item.criadoEm.toDate().toLocaleString() : ''}</Text>
                  </View>
                </View>

                <Text style={styles.avisoMensagem}>{item.mensagem}</Text>

                <View style={styles.interactionRow}>
                  <TouchableOpacity style={styles.likeArea} onPress={() => handleCurtirAviso(item)} activeOpacity={0.75}>
                    <View style={styles.likeIconWrap}>
                      {!usuárioCurtiu && (
                        <Animated.View
                          pointerEvents="none"
                          style={[styles.likeRing, { opacity: ringOpacity, transform: [{ scale: ringScale }] }]}
                        />
                      )}
                      <Animated.View style={likeTransform}>
                        <View style={[styles.likeButton, usuárioCurtiu && styles.likeButtonActive]}>
                          <MaterialCommunityIcons
                            name="thumb-up"
                            size={21}
                            color={usuárioCurtiu ? '#111827' : '#FFB84D'}
                          />
                        </View>
                      </Animated.View>
                    </View>
                    <View>
                      <Text style={styles.likeCount}>{curtidas.length}</Text>
                      <Text style={styles.likeLabel}>{usuárioCurtiu ? 'Você curtiu' : 'Curtir aviso'}</Text>
                    </View>
                  </TouchableOpacity>

                  {permitido && (
                    <View style={styles.adminActions}>
                      <TouchableOpacity style={styles.iconAction} onPress={() => handleEditarAviso(item)} activeOpacity={0.8}>
                        <MaterialIcons name="edit" size={18} color="#67E8F9" />
                      </TouchableOpacity>
                      <TouchableOpacity style={[styles.iconAction, styles.deleteAction]} onPress={() => excluirAviso(item.id!)} activeOpacity={0.8}>
                        <MaterialIcons name="delete-outline" size={19} color="#FFE5E5" />
                      </TouchableOpacity>
                    </View>
                  )}
                </View>

                {permitido && nomesCurtidores.length > 0 && (
                  <View style={styles.curtidoresBox}>
                    <Text style={styles.curtidoresTitle}>Curtiram</Text>
                    <View style={styles.curtidoresChips}>
                      {nomesCurtidores.map(nome => (
                        <View key={nome} style={styles.curtidorChip}>
                          <Text style={styles.curtidorText}>{nome}</Text>
                        </View>
                      ))}
                    </View>
                  </View>
                )}
              </>
            )}
          </LinearGradient>
        </LinearGradient>
      </Animated.View>
    );
  };

  return (
    <LinearGradient colors={['#0B1630', '#161934', '#241A3D']} start={{ x: 0, y: 0 }} end={{ x: 1, y: 1 }} style={styles.bg}>
      <KeyboardAvoidingView style={{ flex: 1 }} behavior={Platform.OS === 'ios' ? 'padding' : undefined}>
        <View style={styles.container}>
          <View style={styles.header}>
            <TouchableOpacity style={styles.headerBtn} onPress={() => navigation.navigate('Inicio')} activeOpacity={0.85}>
              <MaterialCommunityIcons name="home-variant-outline" size={24} color="#43E97B" />
            </TouchableOpacity>
            <View style={styles.headerTitleWrap}>
              <View style={styles.headerTitleIcon}>
                <MaterialCommunityIcons name="bell-ring" size={22} color="#111827" />
              </View>
              <Text style={styles.headerTitle}>Painel de Avisos</Text>
            </View>
            <TouchableOpacity style={styles.headerBtn} onPress={() => navigation.goBack()} activeOpacity={0.85}>
              <MaterialIcons name="keyboard-backspace" size={25} color="#46D7FF" />
            </TouchableOpacity>
          </View>

          {permitido && (
            mostrarCamposNovo ? (
              <LinearGradient colors={['#FFB84D', '#43E97B', '#46D7FF']} start={{ x: 0, y: 0 }} end={{ x: 1, y: 1 }} style={styles.novoAvisoBorder}>
                <LinearGradient colors={['#172044', '#211B3D']} start={{ x: 0, y: 0 }} end={{ x: 1, y: 1 }} style={styles.novoAvisoBox}>
                  <Text style={styles.novoAvisoTítulo}>Novo aviso</Text>
                  <TextInput style={styles.input} placeholder="Título do aviso" value={novoTítulo} onChangeText={setNovoTítulo} placeholderTextColor="#BFD7FF" />
                  <TextInput style={[styles.input, styles.textArea]} placeholder="Digite sua mensagem" value={novoMensagem} onChangeText={setNovoMensagem} multiline placeholderTextColor="#BFD7FF" />
                  <View style={styles.row}>
                    <GradientButton style={{ flex: 1, marginRight: 8 }} onPress={handleCriarAviso}>
                      <Text style={styles.gradientButtonText}>Criar Aviso</Text>
                    </GradientButton>
                    <GradientButton style={{ flex: 1, marginLeft: 8 }} onPress={() => setMostrarCamposNovo(false)} variant="secondary">
                      <Text style={styles.gradientButtonText}>Cancelar</Text>
                    </GradientButton>
                  </View>
                </LinearGradient>
              </LinearGradient>
            ) : (
              <GradientButton style={styles.createShortcut} onPress={() => setMostrarCamposNovo(true)}>
                <MaterialIcons name="add-circle-outline" size={22} color="#111827" />
                <Text style={styles.gradientButtonText}>Criar novo aviso</Text>
              </GradientButton>
            )
          )}

          {loading ? (
            <ActivityIndicator size="large" color="#FFB84D" style={{ marginTop: 30 }} />
          ) : (
            <FlatList
              data={avisos}
              keyExtractor={item => item.id!}
              renderItem={renderItem}
              extraData={usuáriosInfo}
              ListEmptyComponent={<Text style={styles.emptyText}>Nenhum aviso cadastrado.</Text>}
              contentContainerStyle={{ paddingBottom: 30 }}
              showsVerticalScrollIndicator={false}
            />
          )}
        </View>
      </KeyboardAvoidingView>
    </LinearGradient>
  );
}

