import { Platform } from 'react-native';
import { arrayUnion, doc, serverTimestamp, setDoc } from 'firebase/firestore';
import { getToken, MessagePayload, onMessage } from 'firebase/messaging';
import { User } from 'firebase/auth';
import { firestore, messagingPromise } from './firebaseConfig';

const FIREBASE_MESSAGING_SW_PATH = '/firebase-messaging-sw.js';
const FIREBASE_WEB_PUSH_VAPID_KEY = 'BIqMt2i7vb28AEucSAbRyjywLcOVAaDvV2ZTSAr2qVJfbHUI6zZNaZnnz3F8TeCb_CwctlcBvfzk_Jn0x2EOZl4';
const STANDARD_WEB_PUSH_VAPID_KEY = 'BHqZu2NBIz8g7NoCYjOB54kr5U63m36DXngHa9ENGqeX0SK-HCUTHtEwvg5rWTYVMyYYcq0wUH-BniClDK7SJQ0';

let foregroundMessageHandlerRegistered = false;

function getPublicAssetUrl(assetPath: string): string {
  const normalizedAssetPath = assetPath.startsWith('/') ? assetPath : `/${assetPath}`;
  const manifestHref = document.querySelector<HTMLLinkElement>('link[rel="manifest"]')?.href;
  if (!manifestHref) return normalizedAssetPath;

  return new URL(`.${normalizedAssetPath}`, manifestHref).pathname;
}

async function salvarStatusNotificacao(usuario: User, status: string, detalhes?: string) {
  await setDoc(
    doc(firestore, 'usuarios', usuario.uid),
    {
      notificacoesWebStatus: status,
      notificacoesWebDetalhes: detalhes || null,
      notificacoesWebAtualizadoEm: serverTimestamp(),
    },
    { merge: true }
  );
}

async function getReadyServiceWorkerRegistration(): Promise<ServiceWorkerRegistration> {
  const swUrl = getPublicAssetUrl(FIREBASE_MESSAGING_SW_PATH);
  const swScope = new URL('.', new URL(swUrl, window.location.origin)).href;
  const existingRegistration = await navigator.serviceWorker.getRegistration(swScope);
  const registration = existingRegistration || await navigator.serviceWorker.register(swUrl);

  await registration.update().catch(() => undefined);
  await navigator.serviceWorker.ready;

  return registration;
}

function showForegroundNotification(payload: MessagePayload) {
  if (document.visibilityState !== 'visible' || Notification.permission !== 'granted') return;

  const title = payload.notification?.title || payload.data?.title || 'WorshipApp';
  const body = payload.notification?.body || payload.data?.body;
  const url = payload.data?.url;

  const notification = new Notification(title, {
    body,
    icon: getPublicAssetUrl('/icon-512.png'),
    badge: getPublicAssetUrl('/favicon-32.png'),
    data: payload.data,
  });

  notification.onclick = () => {
    notification.close();
    window.focus();

    if (url) {
      window.location.href = new URL(url, window.location.origin).href;
    }
  };
}

function urlBase64ToUint8Array(base64String: string): Uint8Array {
  const padding = '='.repeat((4 - (base64String.length % 4)) % 4);
  const base64 = `${base64String}${padding}`.replace(/-/g, '+').replace(/_/g, '/');
  const rawData = window.atob(base64);
  const outputArray = new Uint8Array(rawData.length);

  for (let i = 0; i < rawData.length; i += 1) {
    outputArray[i] = rawData.charCodeAt(i);
  }

  return outputArray;
}

async function subscribeStandardWebPush(swRegistration: ServiceWorkerRegistration) {
  if (!('PushManager' in window) || !swRegistration.pushManager) return null;

  const existingSubscription = await swRegistration.pushManager.getSubscription();
  if (existingSubscription) return existingSubscription.toJSON();

  const subscription = await swRegistration.pushManager.subscribe({
    userVisibleOnly: true,
    applicationServerKey: urlBase64ToUint8Array(STANDARD_WEB_PUSH_VAPID_KEY),
  });

  return subscription.toJSON();
}

export async function registerFirebaseWebPush(usuario: User | null): Promise<void> {
  if (Platform.OS !== 'web' || !usuario || typeof window === 'undefined') return;
  if (!('Notification' in window) || !('serviceWorker' in navigator)) {
    await salvarStatusNotificacao(usuario, 'unsupported', 'Este navegador nao suporta Push API ou Service Worker.');
    return;
  }

  try {
    const currentPermission = Notification.permission;
    const permission = currentPermission === 'default'
      ? await Notification.requestPermission()
      : currentPermission;

    if (permission !== 'granted') {
      await salvarStatusNotificacao(usuario, permission);
      return;
    }

    const swRegistration = await getReadyServiceWorkerRegistration();
    const webPushSubscription = await subscribeStandardWebPush(swRegistration);
    const messaging = await messagingPromise;

    if (!messaging) {
      if (webPushSubscription) {
        await setDoc(
          doc(firestore, 'usuarios', usuario.uid),
          {
            notificacoesWebAtivas: true,
            notificacoesWebStatus: 'active-web-push',
            notificacoesWebDetalhes: null,
            notificacoesWebAtualizadoEm: serverTimestamp(),
            webPushSubscription,
            webPushSubscriptions: arrayUnion(webPushSubscription),
          },
          { merge: true }
        );
      } else {
        await salvarStatusNotificacao(usuario, 'unsupported', 'Firebase Messaging e Push API nao estao disponiveis neste navegador.');
      }
      return;
    }
    const tokenOptions: {
      serviceWorkerRegistration: ServiceWorkerRegistration;
      vapidKey?: string;
    } = {
      serviceWorkerRegistration: swRegistration,
    };

    if (FIREBASE_WEB_PUSH_VAPID_KEY) {
      tokenOptions.vapidKey = FIREBASE_WEB_PUSH_VAPID_KEY;
    }

    const fcmToken = await getToken(messaging, tokenOptions);
    if (!fcmToken && !webPushSubscription) {
      await salvarStatusNotificacao(usuario, 'no-token', 'Permissao concedida, mas o FCM nao retornou token.');
      return;
    }

    await setDoc(
      doc(firestore, 'usuarios', usuario.uid),
      {
        ...(fcmToken ? {
          fcmToken,
          fcmTokens: arrayUnion(fcmToken),
        } : {}),
        notificacoesWebAtivas: true,
        notificacoesWebStatus: fcmToken ? 'active' : 'active-web-push',
        notificacoesWebDetalhes: null,
        notificacoesWebAtualizadoEm: serverTimestamp(),
        ...(webPushSubscription ? {
          webPushSubscription,
          webPushSubscriptions: arrayUnion(webPushSubscription),
        } : {}),
      },
      { merge: true }
    );

    if (!foregroundMessageHandlerRegistered) {
      foregroundMessageHandlerRegistered = true;
      onMessage(messaging, showForegroundNotification);
    }
  } catch (error) {
    console.log('Nao foi possivel registrar o Firebase Cloud Messaging:', error);
    await salvarStatusNotificacao(
      usuario,
      'error',
      error instanceof Error ? error.message : 'Erro desconhecido ao registrar notificacoes.'
    ).catch(() => undefined);
  }
}
